function url(base: string, path: string, query?: Record<string, unknown>): string {
  const params = new URLSearchParams()
  for (const [name, value] of Object.entries(query ?? {})) {
    if (value === undefined || value === null || value === "") continue
    for (const v of Array.isArray(value) ? value : [value]) params.append(name, String(v))
  }
  const qs = params.toString()
  return base.replace(/\/+$/, "") + path + (qs ? "?" + qs : "")
}

function formData(fields: Record<string, unknown>): FormData {
  const form = new FormData()
  for (const [name, value] of Object.entries(fields)) {
    for (const v of Array.isArray(value) ? value : [value]) {
      if (v === undefined || v === null) continue
      form.append(name, v instanceof Blob ? v : String(v))
    }
  }
  return form
}

async function toError(res: Response): Promise<ApiError> {
  let body: Record<string, unknown> | undefined
  try {
    body = (await res.json()) as Record<string, unknown>
  } catch {
    body = undefined
  }
  return new ApiError(res.status, body, res.headers.get("X-Request-ID") ?? undefined)
}

function filename(disposition: string | null): string {
  if (!disposition) return ""
  const star = /filename\*\s*=\s*UTF-8''([^;]+)/i.exec(disposition)
  if (star) return decodeURIComponent(star[1].trim())
  const plain = /filename\s*=\s*"?([^";]+)"?/i.exec(disposition)
  return plain ? plain[1].trim() : ""
}
